// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(t > 1);
        vm.assume(actor != address(0) && actor != address(c));

        vm.warp(t);
        vm.deal(actor, 20 ether);

        // first deposit at time t: succeeds on both versions
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second deposit at the SAME time t: must revert (P), but M lets it through
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
